-- Упражнения книги 19, глава 30 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-event-loop', 0, 'c', 'Один проход цикла событий', 'AioContext в QEMU умеет четыре вещи: следить за дескрипторами, принимать уведомления, ставить таймеры и запускать отложенные вызовы (bottom halves, BH). В aio_poll() после ожидания порядок такой (util/aio-posix.c, QEMU 10.2.0): завершения io_uring, затем BH, затем готовые обработчики дескрипторов, затем таймеры. Постройте модель на готовых структурах (Loop, Bh, Timer, FdHandler) и реализуйте функции. loop_init обнуляет цикл. loop_add_fd / loop_bh_new / loop_timer_new добавляют обработчик и возвращают его номер (с нуля). loop_bh_schedule(l, bh): если BH ещё не запланирован, пометьте его sched и дайте ему следующий номер ++bh_seq; повторный вызов для уже запланированного ничего не меняет. loop_timer_mod(l, t, expire): взвести таймер на момент expire (armed, номер ++tm_seq). loop_timeout(l, now): как aio_compute_timeout — 0, если запланирован хоть один BH; иначе -1, если нет взведённых таймеров; иначе время до ближайшего (0, если он уже наступил). loop_poll(l, ready, nready, now) выполняет один проход после ожидания и возвращает 1, если вызвался хоть один обработчик, иначе 0: (1) берёт «срез» — все BH, запланированные к началу вызова, снимает с них sched и вызывает от последнего запланированного к первому (так читается async.c: вставка в голову списка; гарантией API это не является); BH, запланированные уже во время прохода, ждут следующего вызова; (2) для каждого дескриптора из ready по порядку массива вызывает обработчик с этим fd (неизвестный fd пропускается); (3) пока есть взведённый таймер с expire <= now, берёт из них наименьший по (expire, номеру), снимает armed ДО вызова (как QEMU) и вызывает; таймер, взведённый из обработчика на уже наступившее время, сработает в этом же проходе. Это лабораторная МОДЕЛЬ, написанная с нуля (не код QEMU): она повторяет порядок действий, прочитанный в исходниках QEMU 10.2.0, а правила модели описаны в условии.', '#include <stdlib.h>
#include <string.h>

#define NH 8
typedef void (*cb_t)(void *opaque);
typedef struct { int fd; cb_t cb; void *opaque; } FdHandler;
typedef struct { int sched; long seq; cb_t cb; void *opaque; } Bh;
typedef struct { int armed; long long expire; long seq; cb_t cb; void *opaque; } Timer;
typedef struct {
    FdHandler fds[NH]; int nfds;
    Bh bh[NH]; int nbh; long bh_seq;
    Timer tm[NH]; int ntm; long tm_seq;
} Loop;

void loop_init(Loop *l) {
    // обнулить структуру
}

int loop_add_fd(Loop *l, int fd, cb_t cb, void *opaque) {
    // запомнить обработчик, вернуть его номер
    return -1;
}

int loop_bh_new(Loop *l, cb_t cb, void *opaque) {
    return -1;
}

void loop_bh_schedule(Loop *l, int bh) {
    // пометить BH как запланированный (один раз)
}

int loop_timer_new(Loop *l, cb_t cb, void *opaque) {
    return -1;
}

void loop_timer_mod(Loop *l, int t, long long expire) {
    // взвести таймер
}

long long loop_timeout(Loop *l, long long now) {
    // 0 / -1 / время до таймера
    return -1;
}

int loop_poll(Loop *l, const int *ready, int nready, long long now) {
    // срез BH, готовые fd, наступившие таймеры
    return 0;
}
', 'Для BH сначала скопируйте в локальный массив индексы и их номера (seq) и снимите sched, и только потом вызывайте: обработчик может запланировать BH заново. Таймеры выбирайте в цикле «найти минимум, снять armed, вызвать».', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n\nstatic Loop L;\nstatic int bh_a, bh_b, bh_c, t1, t2, t3, t4, runs;\n\nstatic void say(void *o) { printf(\"  %s\\n\", (const char *)o); }\nstatic void a_cb(void *o) { (void)o; printf(\"  bh A (schedules bh C)\\n\"); loop_bh_schedule(&L, bh_c); }\nstatic void t4_cb(void *o) {\n    (void)o;\n    printf(\"  timer 4, run %d\\n\", runs + 1);\n    if (++runs < 3)\n        loop_timer_mod(&L, t4, 100);\n}\n\nint main(void) {\n    loop_init(&L);\n    loop_add_fd(&L, 5, say, \"fd 5 handler\");\n    loop_add_fd(&L, 7, say, \"fd 7 handler\");\n    bh_a = loop_bh_new(&L, a_cb, NULL);\n    bh_b = loop_bh_new(&L, say, \"bh B\");\n    bh_c = loop_bh_new(&L, say, \"bh C\");\n    t1 = loop_timer_new(&L, say, \"timer 1 (expires 100)\");\n    t2 = loop_timer_new(&L, say, \"timer 2 (expires 50)\");\n    t3 = loop_timer_new(&L, say, \"timer 3 (expires 100)\");\n\n    printf(\"timeout, nothing pending: %lld\\n\", loop_timeout(&L, 0));\n    loop_timer_mod(&L, t1, 100);\n    loop_timer_mod(&L, t2, 50);\n    loop_timer_mod(&L, t3, 100);\n    printf(\"timeout at now=10: %lld\\n\", loop_timeout(&L, 10));\n    printf(\"timeout at now=60: %lld\\n\", loop_timeout(&L, 60));\n    loop_bh_schedule(&L, bh_a);\n    loop_bh_schedule(&L, bh_b);\n    loop_bh_schedule(&L, bh_b);\n    printf(\"timeout with a scheduled bh: %lld\\n\", loop_timeout(&L, 10));\n\n    int ready[] = { 7, 99, 5 };\n    printf(\"poll 1 (ready fds 7, 99, 5; now=100):\\n\");\n    printf(\"  progress=%d\\n\", loop_poll(&L, ready, 3, 100));\n    printf(\"poll 2:\\n\");\n    printf(\"  progress=%d\\n\", loop_poll(&L, NULL, 0, 100));\n    printf(\"poll 3:\\n\");\n    printf(\"  progress=%d\\n\", loop_poll(&L, NULL, 0, 100));\n    printf(\"timeout when idle again: %lld\\n\", loop_timeout(&L, 100));\n\n    t4 = loop_timer_new(&L, t4_cb, NULL);\n    loop_timer_mod(&L, t4, 100);\n    printf(\"poll 4 (a timer that re-arms itself):\\n\");\n    printf(\"  progress=%d\\n\", loop_poll(&L, NULL, 0, 100));\n    printf(\"runs=%d, timeout=%lld\\n\", runs, loop_timeout(&L, 100));\n    return 0;\n}\n", "expected": ["timeout, nothing pending: -1", "timeout at now=10: 40", "timeout at now=60: 0", "timeout with a scheduled bh: 0", "poll 1 (ready fds 7, 99, 5; now=100):", "  bh B", "  bh A (schedules bh C)", "  fd 7 handler", "  fd 5 handler", "  timer 2 (expires 50)", "  timer 1 (expires 100)", "  timer 3 (expires 100)", "  progress=1", "poll 2:", "  bh C", "  progress=1", "poll 3:", "  progress=0", "timeout when idle again: -1", "poll 4 (a timer that re-arms itself):", "  timer 4, run 1", "  timer 4, run 2", "  timer 4, run 3", "  progress=1", "runs=3, timeout=-1"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-event-notifier', 1, 'c', 'Уведомитель событий на eventfd', 'ioeventfd и irqfd в QEMU — это обёртки EventNotifier над eventfd (util/event_notifier-posix.c, QEMU 10.2.0). Гость пишет в адрес уведомления, KVM увеличивает счётчик eventfd, а обработчик AioContext его читает. Реализуйте по настоящему eventfd (в песочнице он есть). notifier_init(n, active): создайте eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC), запомните fd, пометьте initialized; верните 0 или -errno; при active сразу сделайте notifier_set. notifier_set(n): если не инициализирован — -1; иначе запишите 8 байт со значением 1, повторяя при EINTR; EAGAIN — не ошибка (счётчик переполнен, значит читатель всё равно проснётся); другая ошибка — -errno; успех — 0. notifier_test_and_clear(n): если не инициализирован — 0; иначе прочитайте 8 байт (повторяя при EINTR) и верните 1, если что-то прочиталось, иначе 0 (несколько «пинков» сливаются в один). notifier_cleanup закрывает fd и снимает initialized. drain_kick(n, handler, opaque) — как virtio_queue_host_notifier_read: если test_and_clear вернул 1, вызовите handler(opaque) один раз и верните 1, иначе 0. Пинок, сделанный самим обработчиком, не должен теряться. eventfd здесь настоящий, остальное повторяет логику QEMU своими словами.', '#include <errno.h>
#include <fcntl.h>
#include <stddef.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/eventfd.h>

typedef struct { int fd; int initialized; } Notifier;

int notifier_set(Notifier *n);

int notifier_init(Notifier *n, int active) {
    // eventfd(0, EFD_NONBLOCK | EFD_CLOEXEC)
    return -1;
}

int notifier_set(Notifier *n) {
    // write(fd, &1, 8), EINTR, EAGAIN
    return -1;
}

int notifier_test_and_clear(Notifier *n) {
    // read(fd, &v, 8): 1 или 0
    return 0;
}

void notifier_cleanup(Notifier *n) {
    // close(fd)
}

int drain_kick(Notifier *n, void (*handler)(void *), void *opaque) {
    // test_and_clear, затем handler
    return 0;
}
', 'Чтение из неблокирующего eventfd при нулевом счётчике даёт -1 с errno EAGAIN: это «нет пинков», а не ошибка. Не читайте в цикле до опустошения — одного read хватает, он обнуляет счётчик.', '{"driver": "/*__DRIVER__*/\n#include <poll.h>\n#include <stdio.h>\n\nstatic Notifier N;\nstatic int handled;\n\nstatic int readable(int fd) {\n    struct pollfd p = { fd, POLLIN, 0 };\n    return poll(&p, 1, 0) == 1 && (p.revents & POLLIN);\n}\nstatic void handler(void *o) {\n    (void)o;\n    handled++;\n    printf(\"  handler run %d\\n\", handled);\n    if (handled == 1)\n        notifier_set(&N);          /* a kick that arrives while the handler runs */\n}\n\nint main(void) {\n    Notifier dead = { -1, 0 };\n    printf(\"set before init: %d, test_and_clear before init: %d\\n\", notifier_set(&dead), notifier_test_and_clear(&dead));\n\n    printf(\"init(active=0): %d\\n\", notifier_init(&N, 0));\n    int fl = fcntl(N.fd, F_GETFL), fd = fcntl(N.fd, F_GETFD);\n    printf(\"nonblock=%d cloexec=%d\\n\", (fl & O_NONBLOCK) != 0, (fd & FD_CLOEXEC) != 0);\n    printf(\"nothing pending: readable=%d test_and_clear=%d\\n\", readable(N.fd), notifier_test_and_clear(&N));\n\n    printf(\"three kicks: %d %d %d\\n\", notifier_set(&N), notifier_set(&N), notifier_set(&N));\n    printf(\"readable=%d\\n\", readable(N.fd));\n    printf(\"test_and_clear=%d (kicks are coalesced)\\n\", notifier_test_and_clear(&N));\n    printf(\"readable=%d, again=%d\\n\", readable(N.fd), notifier_test_and_clear(&N));\n\n    printf(\"drain_kick on an idle notifier: %d\\n\", drain_kick(&N, handler, NULL));\n    notifier_set(&N);\n    printf(\"drain_kick after a kick:\\n\");\n    printf(\"  result=%d\\n\", drain_kick(&N, handler, NULL));\n    printf(\"the handler''s own kick is not lost:\\n\");\n    printf(\"  result=%d\\n\", drain_kick(&N, handler, NULL));\n    printf(\"  result=%d\\n\", drain_kick(&N, handler, NULL));\n\n    int old = N.fd;\n    notifier_cleanup(&N);\n    printf(\"after cleanup: fd closed=%d, initialized=%d\\n\", fcntl(old, F_GETFD) < 0 && errno == EBADF, N.initialized);\n\n    Notifier a;\n    printf(\"init(active=1): %d, \", notifier_init(&a, 1));\n    printf(\"pending=%d\\n\", notifier_test_and_clear(&a));\n    notifier_cleanup(&a);\n    return 0;\n}\n", "expected": ["set before init: -1, test_and_clear before init: 0", "init(active=0): 0", "nonblock=1 cloexec=1", "nothing pending: readable=0 test_and_clear=0", "three kicks: 0 0 0", "readable=1", "test_and_clear=1 (kicks are coalesced)", "readable=0, again=0", "drain_kick on an idle notifier: 0", "drain_kick after a kick:", "  handler run 1", "  result=1", "the handler''s own kick is not lost:", "  handler run 2", "  result=1", "  result=0", "after cleanup: fd closed=1, initialized=0", "init(active=1): 0, pending=1"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-virtq-pop', 2, 'c', 'Достать цепочку из virtqueue и вернуть её', 'Раздельная (split) virtqueue состоит из таблицы дескрипторов, кольца avail (гость кладёт номера голов цепочек, счётчик idx растёт) и кольца used (устройство возвращает {id, len}). Ниже готовые структуры Desc, Avail, Used, Vq и Elem; индексы avail->idx и used->idx — 16-битные и переходят через 65535. Реализуйте int vq_pop(Vq *vq, Elem *e) по мотивам virtqueue_split_pop (hw/virtio/virtio.c, QEMU 10.2.0). Результат: 0 — очередь пуста (avail->idx == last_avail_idx, сравнение без «больше/меньше»); 1 — цепочка прочитана; -1 — кольцо испорчено. Порядок: (1) пусто — вернуть 0; (2) если inuse >= num — вернуть -1; (3) head = avail->ring[last_avail_idx % num], и last_avail_idx увеличивается СРАЗУ, ещё до проверок; head >= num — вернуть -1; (4) пройти цепочку от головы: дескриптор с флагом F_WRITE складывается в e->in, без него — в e->out, причём читаемый дескриптор после записываемого — ошибка (-1); если число пройденных дескрипторов стало больше num — ошибка «петля» (-1); при F_NEXT переход на d.next, а d.next >= num — ошибка; (5) успех: e->head = head, inuse++, вернуть 1. vq_push(vq, e, len) возвращает цепочку: used->ring[used->idx % num] = {e->head, len}, затем used->idx++ (16 бит) и inuse--. Это лабораторная МОДЕЛЬ, написанная с нуля (не код QEMU): она повторяет проверки, прочитанные в hw/virtio/virtio.c и hw/block/virtio-blk.c QEMU 10.2.0, а правила модели описаны в условии.', '#include <stdint.h>
#include <string.h>

#define F_NEXT  1
#define F_WRITE 2
#define QMAX 16

typedef struct { uint64_t addr; uint32_t len; uint16_t flags; uint16_t next; } Desc;
typedef struct { uint16_t flags; uint16_t idx; uint16_t ring[QMAX]; } Avail;
typedef struct { uint32_t id; uint32_t len; } UsedElem;
typedef struct { uint16_t flags; uint16_t idx; UsedElem ring[QMAX]; } Used;
typedef struct {
    unsigned num;               /* queue size, a power of two <= QMAX */
    Desc *desc; Avail *avail; Used *used;
    uint16_t last_avail_idx;    /* how far the device has consumed avail */
    unsigned inuse;             /* popped but not yet pushed */
} Vq;
typedef struct {
    int head;
    int out_num, in_num;        /* device-readable and device-writable descriptors */
    Desc out[QMAX], in[QMAX];
} Elem;

int vq_pop(Vq *vq, Elem *e) {
    // пусто / inuse / голова / обход цепочки / успех
    return -1;
}

void vq_push(Vq *vq, const Elem *e, uint32_t len) {
    // записать в used и сдвинуть used->idx
}
', 'Индексы сравнивайте на равенство, а позицию в кольце берите по модулю num. Для проверки порядка достаточно запомнить, был ли уже записываемый дескриптор: in_num > 0.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n\nstatic Desc desc[QMAX];\nstatic Avail avail;\nstatic Used used;\nstatic Vq vq;\n\nstatic void show(const char *what, int r, const Elem *e) {\n    printf(\"%s: result=%d\", what, r);\n    if (r == 1) {\n        printf(\" head=%d out=[\", e->head);\n        for (int i = 0; i < e->out_num; i++)\n            printf(\"%s%u\", i ? \" \" : \"\", e->out[i].len);\n        printf(\"] in=[\");\n        for (int i = 0; i < e->in_num; i++)\n            printf(\"%s%u\", i ? \" \" : \"\", e->in[i].len);\n        printf(\"]\");\n    }\n    printf(\" last_avail=%u inuse=%u\\n\", vq.last_avail_idx, vq.inuse);\n}\nstatic void setd(int i, uint32_t len, uint16_t flags, uint16_t next) {\n    desc[i].addr = 0x1000 + 0x100 * i; desc[i].len = len; desc[i].flags = flags; desc[i].next = next;\n}\nstatic void reset(unsigned num, uint16_t start) {\n    memset(desc, 0, sizeof desc); memset(&avail, 0, sizeof avail); memset(&used, 0, sizeof used);\n    vq = (Vq){ num, desc, &avail, &used, start, 0 };\n}\n\nint main(void) {\n    Elem e;\n\n    /* 1: a normal request: header (out), data and status (in); then a one-descriptor request */\n    reset(8, 0);\n    setd(0, 16, F_NEXT, 5);\n    setd(5, 4096, F_NEXT | F_WRITE, 2);\n    setd(2, 1, F_WRITE, 0);\n    setd(7, 512, F_WRITE, 0);\n    show(\"empty queue\", vq_pop(&vq, &e), &e);\n    avail.ring[0] = 0; avail.ring[1] = 7; avail.idx = 2;\n    show(\"pop 1\", vq_pop(&vq, &e), &e);\n    Elem first = e;\n    show(\"pop 2\", vq_pop(&vq, &e), &e);\n    Elem second = e;\n    show(\"pop 3\", vq_pop(&vq, &e), &e);\n    vq_push(&vq, &second, 513);\n    vq_push(&vq, &first, 4097);\n    printf(\"used: idx=%u ring=[(%u,%u) (%u,%u)] inuse=%u\\n\", used.idx,\n           used.ring[0].id, used.ring[0].len, used.ring[1].id, used.ring[1].len, vq.inuse);\n\n    /* 2: indexes wrap around 65535 */\n    reset(4, 65534);\n    setd(1, 8, F_WRITE, 0);\n    avail.ring[65534 % 4] = 1; avail.ring[65535 % 4] = 1; avail.idx = 0;   /* idx wrapped: two entries available */\n    used.idx = 65535;\n    show(\"wrap pop A\", vq_pop(&vq, &e), &e);\n    vq_push(&vq, &e, 8);\n    show(\"wrap pop B\", vq_pop(&vq, &e), &e);\n    vq_push(&vq, &e, 8);\n    printf(\"used: idx=%u ring[3]=(%u,%u) ring[0]=(%u,%u)\\n\", used.idx, used.ring[3].id, used.ring[3].len, used.ring[0].id, used.ring[0].len);\n    show(\"wrap pop C\", vq_pop(&vq, &e), &e);\n\n    /* 3: broken rings */\n    reset(8, 0);\n    setd(0, 16, F_NEXT, 1);\n    setd(1, 64, F_WRITE | F_NEXT, 2);\n    setd(2, 16, F_NEXT, 3);            /* readable after writable */\n    setd(3, 16, 0, 0);\n    avail.ring[0] = 0; avail.idx = 1;\n    show(\"readable after writable\", vq_pop(&vq, &e), &e);\n\n    reset(8, 0);\n    setd(0, 16, F_NEXT, 1);\n    setd(1, 16, F_NEXT, 0);            /* loop 0 -> 1 -> 0 */\n    avail.ring[0] = 0; avail.idx = 1;\n    show(\"descriptor loop\", vq_pop(&vq, &e), &e);\n\n    reset(8, 0);\n    setd(0, 16, F_NEXT, 9);            /* next >= num */\n    avail.ring[0] = 0; avail.idx = 1;\n    show(\"next out of range\", vq_pop(&vq, &e), &e);\n\n    reset(8, 0);\n    avail.ring[0] = 12; avail.idx = 1; /* head >= num */\n    show(\"head out of range\", vq_pop(&vq, &e), &e);\n\n    reset(2, 0);                       /* the device is not allowed to hold more than num elements */\n    setd(0, 8, F_WRITE, 0); setd(1, 8, F_WRITE, 0);\n    avail.ring[0] = 0; avail.ring[1] = 1; avail.idx = 2;\n    vq_pop(&vq, &e); vq_pop(&vq, &e);\n    avail.idx = 3;\n    show(\"too many in flight\", vq_pop(&vq, &e), &e);\n    return 0;\n}\n", "expected": ["empty queue: result=0 last_avail=0 inuse=0", "pop 1: result=1 head=0 out=[16] in=[4096 1] last_avail=1 inuse=1", "pop 2: result=1 head=7 out=[] in=[512] last_avail=2 inuse=2", "pop 3: result=0 last_avail=2 inuse=2", "used: idx=2 ring=[(7,513) (0,4097)] inuse=0", "wrap pop A: result=1 head=1 out=[] in=[8] last_avail=65535 inuse=1", "wrap pop B: result=1 head=1 out=[] in=[8] last_avail=0 inuse=1", "used: idx=1 ring[3]=(1,8) ring[0]=(1,8)", "wrap pop C: result=0 last_avail=0 inuse=0", "readable after writable: result=-1 last_avail=1 inuse=0", "descriptor loop: result=-1 last_avail=1 inuse=0", "next out of range: result=-1 last_avail=1 inuse=0", "head out of range: result=-1 last_avail=1 inuse=0", "too many in flight: result=-1 last_avail=2 inuse=2"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-blk-request', 3, 'c', 'Разобрать запрос virtio-blk', 'Запрос virtio-blk приходит цепочкой: читаемая часть (out) начинается 16-байтным заголовком {u32 type, u32 ioprio, u64 sector}, малый порядок байт; записываемая часть (in) кончается одним байтом статуса. Данные чтения лежат в in (до статуса), данные записи — в out (после заголовка). Память гостя здесь — массив mem, а кусок описан Seg {off, len}. Реализуйте три функции по мотивам virtio_blk_handle_request и virtio_blk_sect_range_ok (hw/block/virtio-blk.c, QEMU 10.2.0). blk_parse(mem, r, p): вернуть -1 (устройство «сломано»), если out_num < 1 или in_num < 1; если во всех out вместе меньше 16 байт (заголовок может быть разрезан между кусками — собирайте его по кускам); если последний кусок in короче 1 байта. Иначе заполните p и верните 0: status_off — адрес последнего байта последнего куска in; type = первые 4 байта; sector = следующие 8 после ioprio. Вид: type & ~(T_OUT | T_BARRIER) равно T_IN (0) — чтение, если бит T_OUT сброшен, и запись, если он установлен (p->nbytes: для записи размер out минус 16, для чтения размер in минус 1; sector берётся только для них); T_FLUSH (4) — K_FLUSH; T_GET_ID (8) — K_GET_ID; иначе K_UNSUPP. blk_range_ok(p, total_sectors): 0, если nbytes не кратно 512, или sector > total_sectors, или nbytes/512 > total_sectors - sector; иначе 1. blk_set_status(mem, p, status) записывает байт статуса. Это лабораторная МОДЕЛЬ, написанная с нуля (не код QEMU): она повторяет проверки, прочитанные в hw/virtio/virtio.c и hw/block/virtio-blk.c QEMU 10.2.0, а правила модели описаны в условии.', '#include <stdint.h>
#include <string.h>

#define T_IN      0u
#define T_OUT     1u
#define T_FLUSH   4u
#define T_GET_ID  8u
#define T_BARRIER 0x80000000u
#define S_OK     0
#define S_IOERR  1
#define S_UNSUPP 2

typedef struct { uint64_t off; uint32_t len; } Seg;        /* a piece of guest memory */
typedef struct { int out_num, in_num; Seg out[8], in[8]; } Req;
enum { K_READ, K_WRITE, K_FLUSH, K_GET_ID, K_UNSUPP };
typedef struct {
    int kind;
    uint64_t sector;
    uint64_t nbytes;            /* data bytes of a read/write */
    uint64_t status_off;        /* where the status byte lives in guest memory */
} Parsed;

int blk_parse(const uint8_t *mem, const Req *r, Parsed *p) {
    // -1 при сломанном запросе; иначе вид, сектор, размер, адрес статуса
    return -1;
}

int blk_range_ok(const Parsed *p, uint64_t total_sectors) {
    // кратность 512 и границы диска
    return 0;
}

void blk_set_status(uint8_t *mem, const Parsed *p, uint8_t status) {
    // записать байт статуса
}
', 'Собирайте заголовок побайтно по кускам out, пока не наберёте 16 байт; размеры считайте суммой len. Статус — последний байт ПОСЛЕДНЕГО куска in, а не первого.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n\nstatic uint8_t mem[16384];\nstatic const char *KIND[] = { \"read\", \"write\", \"flush\", \"get_id\", \"unsupported\" };\n\nstatic void put_hdr(uint64_t off, uint32_t type, uint64_t sector) {\n    for (int i = 0; i < 4; i++) mem[off + i] = type >> (8 * i);\n    for (int i = 0; i < 4; i++) mem[off + 4 + i] = 0;\n    for (int i = 0; i < 8; i++) mem[off + 8 + i] = sector >> (8 * i);\n}\nstatic void run(const char *name, const Req *r, uint64_t total_sectors) {\n    Parsed p;\n    int rc = blk_parse(mem, r, &p);\n    if (rc) {\n        printf(\"%s: broken request (rc=%d)\\n\", name, rc);\n        return;\n    }\n    int ok = blk_range_ok(&p, total_sectors);\n    uint8_t st = S_OK;\n    if (p.kind == K_UNSUPP) st = S_UNSUPP;\n    else if ((p.kind == K_READ || p.kind == K_WRITE) && !ok) st = S_IOERR;\n    mem[p.status_off] = 0xEE;\n    blk_set_status(mem, &p, st);\n    printf(\"%s: %s sector=%llu bytes=%llu range_ok=%d status_off=%llu status=%u\\n\", name, KIND[p.kind],\n           (unsigned long long)p.sector, (unsigned long long)p.nbytes, ok, (unsigned long long)p.status_off, mem[p.status_off]);\n}\n\nint main(void) {\n    Req r;\n\n    /* read of 8 sectors: header, then 2 data pieces and the status piece */\n    memset(&r, 0, sizeof r);\n    put_hdr(0, T_IN, 2048);\n    r.out_num = 1; r.out[0] = (Seg){ 0, 16 };\n    r.in_num = 3; r.in[0] = (Seg){ 4096, 2048 }; r.in[1] = (Seg){ 8192, 2048 }; r.in[2] = (Seg){ 100, 1 };\n    run(\"read\", &r, 100000);\n\n    /* write of 1 sector; the header is split over two pieces (10 + 6 bytes) */\n    memset(&r, 0, sizeof r);\n    put_hdr(300, T_OUT, 7);\n    r.out_num = 3; r.out[0] = (Seg){ 300, 10 }; r.out[1] = (Seg){ 310, 6 }; r.out[2] = (Seg){ 4096, 512 };\n    r.in_num = 1; r.in[0] = (Seg){ 200, 1 };\n    run(\"write\", &r, 100000);\n\n    /* a read whose last in piece is bigger than 1: the status is its last byte */\n    memset(&r, 0, sizeof r);\n    put_hdr(400, T_IN, 0);\n    r.out_num = 1; r.out[0] = (Seg){ 400, 16 };\n    r.in_num = 1; r.in[0] = (Seg){ 5000, 513 };\n    run(\"read 1 piece\", &r, 100000);\n\n    /* a read past the end of the disk */\n    memset(&r, 0, sizeof r);\n    put_hdr(500, T_IN, 99999);\n    r.out_num = 1; r.out[0] = (Seg){ 500, 16 };\n    r.in_num = 2; r.in[0] = (Seg){ 6000, 1024 }; r.in[1] = (Seg){ 600, 1 };\n    run(\"read past the end\", &r, 100000);\n\n    /* a read whose size is not a multiple of 512 */\n    memset(&r, 0, sizeof r);\n    put_hdr(500, T_IN, 5);\n    r.out_num = 1; r.out[0] = (Seg){ 500, 16 };\n    r.in_num = 2; r.in[0] = (Seg){ 6000, 700 }; r.in[1] = (Seg){ 600, 1 };\n    run(\"read 700 bytes\", &r, 100000);\n\n    /* flush, get_id, barrier flag and an unknown type */\n    uint32_t types[] = { T_FLUSH, T_GET_ID, T_BARRIER | T_IN, 99 };\n    const char *names[] = { \"flush\", \"get_id\", \"barrier read\", \"unknown 99\" };\n    for (int i = 0; i < 4; i++) {\n        memset(&r, 0, sizeof r);\n        put_hdr(700, types[i], 3);\n        r.out_num = 1; r.out[0] = (Seg){ 700, 16 };\n        r.in_num = 2; r.in[0] = (Seg){ 7000, 512 }; r.in[1] = (Seg){ 800 + i, 1 };\n        run(names[i], &r, 100000);\n    }\n\n    /* broken requests */\n    memset(&r, 0, sizeof r);\n    r.in_num = 1; r.in[0] = (Seg){ 10, 1 };\n    run(\"no out piece\", &r, 100000);\n    memset(&r, 0, sizeof r);\n    r.out_num = 1; r.out[0] = (Seg){ 0, 16 };\n    run(\"no in piece\", &r, 100000);\n    memset(&r, 0, sizeof r);\n    r.out_num = 2; r.out[0] = (Seg){ 0, 10 }; r.out[1] = (Seg){ 20, 5 };\n    r.in_num = 1; r.in[0] = (Seg){ 10, 1 };\n    run(\"header too short\", &r, 100000);\n    memset(&r, 0, sizeof r);\n    put_hdr(0, T_IN, 0);\n    r.out_num = 1; r.out[0] = (Seg){ 0, 16 };\n    r.in_num = 2; r.in[0] = (Seg){ 4096, 512 }; r.in[1] = (Seg){ 10, 0 };\n    run(\"empty status piece\", &r, 100000);\n    return 0;\n}\n", "expected": ["read: read sector=2048 bytes=4096 range_ok=1 status_off=100 status=0", "write: write sector=7 bytes=512 range_ok=1 status_off=200 status=0", "read 1 piece: read sector=0 bytes=512 range_ok=1 status_off=5512 status=0", "read past the end: read sector=99999 bytes=1024 range_ok=0 status_off=600 status=1", "read 700 bytes: read sector=5 bytes=700 range_ok=0 status_off=600 status=1", "flush: flush sector=0 bytes=0 range_ok=1 status_off=800 status=0", "get_id: get_id sector=0 bytes=0 range_ok=1 status_off=801 status=0", "barrier read: read sector=3 bytes=512 range_ok=1 status_off=802 status=0", "unknown 99: unsupported sector=0 bytes=0 range_ok=1 status_off=803 status=2", "no out piece: broken request (rc=-1)", "no in piece: broken request (rc=-1)", "header too short: broken request (rc=-1)", "empty status piece: broken request (rc=-1)"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-vcpu-loop', 4, 'c', 'Цикл потока vCPU и замок BQL', 'В QEMU 10.2.0 поток vCPU (kvm_vcpu_thread_fn) входит в kvm_cpu_exec (accel/kvm/kvm-all.c): функция отпускает Big QEMU Lock (bql_unlock) и крутит ioctl(KVM_RUN) в цикле, пока обработчик выхода возвращает 0. Эту работу из главы 28 нужно повторить с учётом замка. Реализуйте int vcpu_exec(int vcpufd, struct kvm_run *run). Поток входит с ЗАХВАЧЕННЫМ замком. (1) Сразу вызовите bql_unlock(). (2) В цикле вызывайте ioctl(vcpufd, KVM_RUN, 0). При ошибке: EINTR или EAGAIN — результат RUN_INTERRUPT, выход из цикла; любая другая — RUN_ERROR. (3) Иначе смотрите run->exit_reason. KVM_EXIT_IO: данные лежат по адресу (uint8_t *)run + run->io.data_offset, count раз вызовите dev_pio(port, ptr, size, direction == KVM_EXIT_IO_OUT), сдвигая ptr на size; результат RUN_CONTINUE. KVM_EXIT_MMIO: один вызов dev_mmio(phys_addr, data, len, is_write), RUN_CONTINUE. Эти два обработчика вызываются БЕЗ замка (код устройства берёт его сам, если нужно). KVM_EXIT_HLT: возьмите замок, результат — handle_halt(), отпустите замок. KVM_EXIT_SHUTDOWN: request_reset() и RUN_INTERRUPT. KVM_EXIT_SYSTEM_EVENT по run->system_event.type: SHUTDOWN — request_shutdown() и RUN_INTERRUPT; RESET — request_reset() и RUN_INTERRUPT; CRASH — под замком guest_panicked() и RUN_CONTINUE; другой тип — RUN_ERROR. Любой другой exit_reason (в том числе KVM_EXIT_INTERNAL_ERROR) — RUN_ERROR. (4) Цикл продолжается, пока результат RUN_CONTINUE. (5) После цикла ВЕРНИТЕ замок (bql_lock); если результат отрицательный, вызовите vm_stop() (под замком). Функция возвращает результат. Это лабораторная МОДЕЛЬ, написанная с нуля (не код QEMU): она повторяет порядок действий, прочитанный в исходниках QEMU 10.2.0, а правила модели описаны в условии. KVM_RUN здесь подменяет модель через -Wl,--wrap=ioctl; константы и структуры kvm_run настоящие, из linux/kvm.h.', '#include <errno.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <linux/kvm.h>

enum { RUN_ERROR = -1, RUN_CONTINUE = 0, RUN_INTERRUPT = 1, RUN_HLT = 2 };

/* provided by the environment: the BQL and the device model */
void bql_lock(void);
void bql_unlock(void);
void dev_pio(uint16_t port, uint8_t *data, int size, int is_write);
void dev_mmio(uint64_t addr, uint8_t *data, uint32_t len, int is_write);
int handle_halt(void);         /* needs the BQL; RUN_HLT = the vCPU must sleep, 0 = go on */
void request_reset(void);
void request_shutdown(void);
void guest_panicked(void);     /* needs the BQL */
void vm_stop(void);            /* needs the BQL */

int vcpu_exec(int vcpufd, struct kvm_run *run) {
    // bql_unlock; цикл KVM_RUN; разбор exit_reason; bql_lock; vm_stop при ошибке
    return RUN_ERROR;
}
', 'Замок: вошли с замком, отпустили до цикла, вернули после цикла; внутри цикла берите его только вокруг HLT и CRASH. Результат одной итерации — переменная ret, цикл do { ... } while (ret == RUN_CONTINUE).', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <string.h>\n\nstatic int bql;                          /* 1 while \"this thread\" holds the BQL */\nvoid bql_lock(void) { if (bql) printf(\"  BUG: bql_lock while held\\n\"); bql = 1; }\nvoid bql_unlock(void) { if (!bql) printf(\"  BUG: bql_unlock while not held\\n\"); bql = 0; }\n\nvoid dev_pio(uint16_t port, uint8_t *data, int size, int is_write) {\n    if (!is_write)\n        for (int i = 0; i < size; i++) data[i] = 0xA0 + i;\n    printf(\"  pio %s port=0x%x size=%d data=0x%02x bql=%d\\n\", is_write ? \"out\" : \"in\", port, size, data[0], bql);\n}\nvoid dev_mmio(uint64_t addr, uint8_t *data, uint32_t len, int is_write) {\n    if (!is_write)\n        memset(data, 0x5A, len);\n    printf(\"  mmio %s addr=0x%llx len=%u data=0x%02x bql=%d\\n\", is_write ? \"write\" : \"read\", (unsigned long long)addr, len, data[0], bql);\n}\nstatic int pending_irq;\nint handle_halt(void) {\n    printf(\"  halt bql=%d pending_irq=%d\\n\", bql, pending_irq);\n    if (pending_irq) { pending_irq = 0; return 0; }\n    return RUN_HLT;\n}\nvoid request_reset(void) { printf(\"  request_reset bql=%d\\n\", bql); }\nvoid request_shutdown(void) { printf(\"  request_shutdown bql=%d\\n\", bql); }\nvoid guest_panicked(void) { printf(\"  guest_panicked bql=%d\\n\", bql); }\nvoid vm_stop(void) { printf(\"  vm_stop bql=%d\\n\", bql); }\n\nenum { S_IO_OUT, S_IO_OUT2, S_IO_IN, S_MMIO_W, S_MMIO_R, S_HLT, S_SHUTDOWN, S_SYS_SHUTDOWN, S_SYS_RESET, S_SYS_CRASH, S_INTERNAL, S_EINTR, S_EAGAIN, S_EFAULT };\nstatic int script[16], nscript, pos;\nstatic struct kvm_run *the_run;\nstatic uint8_t area[4096];\n\nint __wrap_ioctl(int fd, unsigned long req, ...) {\n    (void)fd;\n    if (req != KVM_RUN) { errno = ENOTTY; return -1; }\n    struct kvm_run *r = the_run;\n    uint8_t *data = (uint8_t *)r + 2048;\n    memset(r, 0, 64);\n    int step = script[pos++];\n    printf(\" KVM_RUN #%d bql=%d\\n\", pos, bql);\n    switch (step) {\n    case S_IO_OUT:  r->exit_reason = KVM_EXIT_IO; r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.port = 0x3f8; r->io.count = 1; r->io.data_offset = 2048; data[0] = ''H''; break;\n    case S_IO_OUT2: r->exit_reason = KVM_EXIT_IO; r->io.direction = KVM_EXIT_IO_OUT; r->io.size = 1; r->io.port = 0x3f8; r->io.count = 2; r->io.data_offset = 2048; data[0] = ''o''; data[1] = ''k''; break;\n    case S_IO_IN:   r->exit_reason = KVM_EXIT_IO; r->io.direction = KVM_EXIT_IO_IN; r->io.size = 2; r->io.port = 0x60; r->io.count = 1; r->io.data_offset = 2048; break;\n    case S_MMIO_W:  r->exit_reason = KVM_EXIT_MMIO; r->mmio.phys_addr = 0xfee00000; r->mmio.len = 4; r->mmio.is_write = 1; r->mmio.data[0] = 0x11; break;\n    case S_MMIO_R:  r->exit_reason = KVM_EXIT_MMIO; r->mmio.phys_addr = 0xfee00020; r->mmio.len = 4; r->mmio.is_write = 0; break;\n    case S_HLT:     r->exit_reason = KVM_EXIT_HLT; break;\n    case S_SHUTDOWN: r->exit_reason = KVM_EXIT_SHUTDOWN; break;\n    case S_SYS_SHUTDOWN: r->exit_reason = KVM_EXIT_SYSTEM_EVENT; r->system_event.type = KVM_SYSTEM_EVENT_SHUTDOWN; break;\n    case S_SYS_RESET: r->exit_reason = KVM_EXIT_SYSTEM_EVENT; r->system_event.type = KVM_SYSTEM_EVENT_RESET; break;\n    case S_SYS_CRASH: r->exit_reason = KVM_EXIT_SYSTEM_EVENT; r->system_event.type = KVM_SYSTEM_EVENT_CRASH; break;\n    case S_INTERNAL: r->exit_reason = KVM_EXIT_INTERNAL_ERROR; break;\n    case S_EINTR:  errno = EINTR; return -1;\n    case S_EAGAIN: errno = EAGAIN; return -1;\n    case S_EFAULT: errno = EFAULT; return -1;\n    }\n    return 0;\n}\n\nstatic void scenario(const char *name, int pirq, int n, const int *steps) {\n    memcpy(script, steps, n * sizeof(int));\n    nscript = n; pos = 0; pending_irq = pirq; bql = 1;\n    printf(\"%s:\\n\", name);\n    int r = vcpu_exec(3, the_run);\n    printf(\" result=%d, steps used=%d, bql=%d\\n\", r, pos, bql);\n}\n\nint main(void) {\n    the_run = (struct kvm_run *)area;\n    { int s[] = { S_IO_OUT, S_IO_OUT2, S_MMIO_W, S_MMIO_R, S_IO_IN, S_HLT }; scenario(\"serial output, MMIO, then HLT\", 0, 6, s); }\n    { int s[] = { S_HLT, S_IO_OUT, S_EINTR }; scenario(\"HLT with a pending interrupt, then EINTR\", 1, 3, s); }\n    { int s[] = { S_SYS_CRASH, S_IO_OUT, S_INTERNAL }; scenario(\"crash event, then an internal error\", 0, 3, s); }\n    { int s[] = { S_MMIO_W, S_SHUTDOWN, S_IO_OUT }; scenario(\"triple fault (KVM_EXIT_SHUTDOWN)\", 0, 3, s); }\n    { int s[] = { S_SYS_SHUTDOWN }; scenario(\"system event: shutdown\", 0, 1, s); }\n    { int s[] = { S_SYS_RESET }; scenario(\"system event: reset\", 0, 1, s); }\n    { int s[] = { S_EAGAIN }; scenario(\"EAGAIN\", 0, 1, s); }\n    { int s[] = { S_IO_OUT, S_EFAULT }; scenario(\"ioctl fails with EFAULT\", 0, 2, s); }\n    return 0;\n}\n", "expected": ["serial output, MMIO, then HLT:", " KVM_RUN #1 bql=0", "  pio out port=0x3f8 size=1 data=0x48 bql=0", " KVM_RUN #2 bql=0", "  pio out port=0x3f8 size=1 data=0x6f bql=0", "  pio out port=0x3f8 size=1 data=0x6b bql=0", " KVM_RUN #3 bql=0", "  mmio write addr=0xfee00000 len=4 data=0x11 bql=0", " KVM_RUN #4 bql=0", "  mmio read addr=0xfee00020 len=4 data=0x5a bql=0", " KVM_RUN #5 bql=0", "  pio in port=0x60 size=2 data=0xa0 bql=0", " KVM_RUN #6 bql=0", "  halt bql=1 pending_irq=0", " result=2, steps used=6, bql=1", "HLT with a pending interrupt, then EINTR:", " KVM_RUN #1 bql=0", "  halt bql=1 pending_irq=1", " KVM_RUN #2 bql=0", "  pio out port=0x3f8 size=1 data=0x48 bql=0", " KVM_RUN #3 bql=0", " result=1, steps used=3, bql=1", "crash event, then an internal error:", " KVM_RUN #1 bql=0", "  guest_panicked bql=1", " KVM_RUN #2 bql=0", "  pio out port=0x3f8 size=1 data=0x48 bql=0", " KVM_RUN #3 bql=0", "  vm_stop bql=1", " result=-1, steps used=3, bql=1", "triple fault (KVM_EXIT_SHUTDOWN):", " KVM_RUN #1 bql=0", "  mmio write addr=0xfee00000 len=4 data=0x11 bql=0", " KVM_RUN #2 bql=0", "  request_reset bql=0", " result=1, steps used=2, bql=1", "system event: shutdown:", " KVM_RUN #1 bql=0", "  request_shutdown bql=0", " result=1, steps used=1, bql=1", "system event: reset:", " KVM_RUN #1 bql=0", "  request_reset bql=0", " result=1, steps used=1, bql=1", "EAGAIN:", " KVM_RUN #1 bql=0", " result=1, steps used=1, bql=1", "ioctl fails with EFAULT:", " KVM_RUN #1 bql=0", "  pio out port=0x3f8 size=1 data=0x48 bql=0", " KVM_RUN #2 bql=0", "  vm_stop bql=1", " result=-1, steps used=2, bql=1"], "flags": "-std=gnu11 -O1 -Wall -Wl,--wrap=ioctl"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-coroutine', 5, 'c', 'Корутины на ucontext', 'Блочный слой QEMU написан как последовательный код на корутинах: blk_aio_preadv создаёт корутину (qemu_coroutine_create) и входит в неё, она отправляет запрос и уступает управление (qemu_coroutine_yield), а когда ввод-вывод завершается, цикл событий входит в неё снова. В сборке для Linux по умолчанию используется бэкенд ucontext (meson.build QEMU 10.2.0 предпочитает его, а запасной — sigaltstack). Напишите упрощённый вариант на makecontext/swapcontext. Структура Coroutine уже описана. co_create(entry, opaque): выделите структуру (calloc) и стек CO_STACK байт, подготовьте ctx (getcontext, uc_stack, uc_link = &co->caller, makecontext с функцией без аргументов); корутина НЕ запускается. co_enter(co): если корутина уже в работе (entered) или завершилась (done), вернуть -1 (QEMU в этом случае вызывает abort; в модели нужен код возврата); иначе пометить entered, запомнить prev = текущая корутина, сделать co текущей, swapcontext(&co->caller, &co->ctx); когда управление вернулось (уступка или конец) — вернуть текущей prev, снять entered, вернуть 0. Корутина, дойдя до конца entry, помечается done. co_yield(): вне корутины -1; иначе swapcontext(&co->ctx, &co->caller) и после возобновления 0. co_self() — текущая корутина или NULL; co_done(co) — завершена ли; co_free(co) освобождает стек и структуру. Это лабораторная МОДЕЛЬ, написанная с нуля (не код QEMU): она повторяет порядок действий, прочитанный в исходниках QEMU 10.2.0, а правила модели описаны в условии.', '#include <stdlib.h>
#include <ucontext.h>

#define CO_STACK 131072

typedef struct Coroutine Coroutine;
typedef void (*CoEntry)(void *opaque);
struct Coroutine {
    ucontext_t ctx;        /* the coroutine''s own context */
    ucontext_t caller;     /* where to go back on yield or end */
    CoEntry entry;
    void *opaque;
    char *stack;
    int entered;           /* between enter and yield/end */
    int done;
    Coroutine *prev;       /* the coroutine that was current at enter, or NULL */
};

Coroutine *co_create(CoEntry entry, void *opaque) {
    // calloc, стек, getcontext/makecontext (не запускать)
    return NULL;
}

int co_enter(Coroutine *co) {
    // -1 если entered или done; иначе swapcontext к корутине
    return -1;
}

int co_yield(void) {
    // -1 вне корутины; иначе swapcontext к вызвавшему
    return -1;
}

Coroutine *co_self(void) {
    return NULL;
}

int co_done(Coroutine *co) {
    return 0;
}

void co_free(Coroutine *co) {
}
', 'makecontext принимает функцию без аргументов, поэтому entry и opaque берите из глобальной переменной «текущая корутина». Контекст возврата co->caller записывается заново при каждом co_enter, а uc_link указывает на него, так что конец entry сам вернётся в co_enter.', '{"driver": "/*__DRIVER__*/\n#include <stdio.h>\n#include <string.h>\n\nstatic Coroutine *pending[4];\nstatic int npending;\nstatic Coroutine *inner;\n\nstatic void req_co(void *o) {\n    const char *name = o;\n    int local = 40 + (int)strlen(name);\n    printf(\"  %s: submitted, running inside a coroutine: %d\\n\", name, co_self() != NULL);\n    pending[npending++] = co_self();\n    co_yield();\n    printf(\"  %s: completed, local=%d\\n\", name, local);\n}\nstatic void inner_co(void *o) {\n    (void)o;\n    printf(\"  inner: start\\n\");\n    co_yield();\n    printf(\"  inner: end\\n\");\n}\nstatic void outer_co(void *o) {\n    (void)o;\n    printf(\"  outer: start\\n\");\n    inner = co_create(inner_co, NULL);\n    co_enter(inner);\n    printf(\"  outer: inner yielded back to outer\\n\");\n    co_yield();\n    printf(\"  outer: resumed, resuming inner\\n\");\n    co_enter(inner);\n    printf(\"  outer: end\\n\");\n}\nstatic void selfenter_co(void *o) {\n    (void)o;\n    int r = co_enter(co_self());\n    printf(\"  entering myself: %d\\n\", r);\n}\n\nint main(void) {\n    int y = co_yield();\n    printf(\"outside a coroutine: self=%d yield=%d\\n\", co_self() != NULL, y);\n\n    Coroutine *a = co_create(req_co, \"read-A\"), *b = co_create(req_co, \"write-B\");\n    printf(\"created: done=%d %d, nothing ran yet\\n\", co_done(a), co_done(b));\n    printf(\"enter A:\\n\"); co_enter(a);\n    printf(\"enter B:\\n\"); co_enter(b);\n    printf(\"completions arrive in the other order:\\n\");\n    printf(\" B:\\n\"); co_enter(pending[1]);\n    printf(\" A:\\n\"); co_enter(pending[0]);\n    printf(\"done: %d %d, enter a finished one: %d\\n\", co_done(a), co_done(b), co_enter(a));\n    co_free(a); co_free(b);\n\n    Coroutine *o = co_create(outer_co, NULL);\n    printf(\"nested:\\n\");\n    co_enter(o);\n    printf(\"main: outer yielded (outer done=%d, inner done=%d)\\n\", co_done(o), co_done(inner));\n    co_enter(o);\n    printf(\"main: outer done=%d, inner done=%d, self=%d\\n\", co_done(o), co_done(inner), co_self() != NULL);\n    co_free(inner); co_free(o);\n\n    Coroutine *s = co_create(selfenter_co, NULL);\n    co_enter(s);\n    printf(\"selfenter done=%d\\n\", co_done(s));\n    co_free(s);\n    return 0;\n}\n", "expected": ["outside a coroutine: self=0 yield=-1", "created: done=0 0, nothing ran yet", "enter A:", "  read-A: submitted, running inside a coroutine: 1", "enter B:", "  write-B: submitted, running inside a coroutine: 1", "completions arrive in the other order:", " B:", "  write-B: completed, local=47", " A:", "  read-A: completed, local=46", "done: 1 1, enter a finished one: -1", "nested:", "  outer: start", "  inner: start", "  outer: inner yielded back to outer", "main: outer yielded (outer done=0, inner done=0)", "  outer: resumed, resuming inner", "  inner: end", "  outer: end", "main: outer done=1, inner done=1, self=0", "  entering myself: -1", "selfenter done=1"], "flags": "-std=gnu11 -O1 -Wall"}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-thread-classify', 6, 'func', 'Кто есть кто среди потоков QEMU', 'Команда ps -T -p <pid> -o spid,comm печатает потоки процесса QEMU. Если QEMU запущен с -name ...,debug-threads=on, потоки называются так (по исходникам QEMU 10.2.0): vCPU при ускорителе KVM — "CPU <n>/KVM" (accel/kvm/kvm-accel-ops.c), iothread — "IO <id>" (iothread.c), пул блокирующих задач — "worker" (util/thread-pool.c), RCU — "call_rcu", VNC — "vnc_worker"; главный поток — тот, чей SPID равен pid процесса. Напишите функцию classify_threads(pid, text): text — вывод ps (первая строка — заголовок "SPID COMMAND", которую нужно пропустить; имена потоков могут содержать пробелы). Верните словарь с ключами: "main" (SPID главного потока, а если его нет в выводе — 0), "vcpus" (список пар [номер, SPID], по возрастанию номера), "iothreads" (список пар [id, SPID], по возрастанию id как строки), "workers" (сколько потоков с именем worker), "rcu" (сколько call_rcu) и "other" (отсортированный список имён всех остальных потоков, включая одинаковые). Поток без опознанного имени (например, потому что debug-threads выключен и все потоки называются как процесс) попадает в "other".', 'def classify_threads(pid, text):
    pass
', 'Разбейте строку на SPID и остаток: line.split(None, 1). Заголовок отсеивается тем, что его первое поле не число. Имена vCPU и iothread разбирайте регулярными выражениями или startswith/endswith.', '{"func": "classify_threads", "tests": [{"args": [4101, "  SPID COMMAND\n  4101 qemu-system-x86\n  4107 call_rcu\n  4108 IO mon_iothread\n  4112 CPU 0/KVM\n  4113 CPU 1/KVM\n  4114 CPU 10/KVM\n  4120 IO iothread1\n  4131 worker\n  4132 worker\n  4140 vnc_worker\n"], "expected": {"main": 4101, "vcpus": [[0, 4112], [1, 4113], [10, 4114]], "iothreads": [["iothread1", 4120], ["mon_iothread", 4108]], "workers": 2, "rcu": 1, "other": ["vnc_worker"]}}, {"args": [4101, "  SPID COMMAND\n  4101 qemu-system-x86\n  4102 qemu-system-x86\n  4103 qemu-system-x86\n"], "expected": {"main": 4101, "vcpus": [], "iothreads": [], "workers": 0, "rcu": 0, "other": ["qemu-system-x86", "qemu-system-x86"]}}, {"args": [4101, "SPID COMMAND\n"], "expected": {"main": 0, "vcpus": [], "iothreads": [], "workers": 0, "rcu": 0, "other": []}}, {"args": [77, "    SPID COMMAND\n      77 qemu-kvm\n      90 CPU 2/KVM\n      91 CPU 3/KVM\n      92 CPU 1/KVM\n      95 CPU 0/KVM\n"], "expected": {"main": 77, "vcpus": [[0, 95], [1, 92], [2, 90], [3, 91]], "iothreads": [], "workers": 0, "rcu": 0, "other": []}}, {"args": [5, "SPID COMMAND\n5 qemu\n6 IO io-b\n7 IO io-a\n8 IO\n9 CPUS/KVM\n10 worker \n"], "expected": {"main": 5, "vcpus": [], "iothreads": [["io-a", 7], ["io-b", 6]], "workers": 1, "rcu": 0, "other": ["CPUS/KVM", "IO"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-trace-lifecycle', 7, 'func', 'Жизнь запроса диска в журнале trace-событий', 'Запустив QEMU с --trace "virtio_blk_*" (журнал-бэкенд log, строки вида pid@сек.мкс:имя аргументы, как в docs/devel/tracing.rst), получают события из hw/block/trace-events и hw/virtio/trace-events QEMU 10.2.0. Для чтения и записи virtio-blk порядок такой: virtio_blk_handle_read или virtio_blk_handle_write (параметры "vdev <p> req <p> sector <n> nsectors <n>") → virtio_blk_rw_complete ("vdev <p> req <p> ret <n>") → virtio_blk_req_complete ("vdev <p> req <p> status <n>", 0 — успех). Если запрос отвергнут ещё до отправки (например, сектор вне диска), rw_complete не будет: сразу req_complete со статусом не 0. Запрос flush или get_id не пишет handle-события, и его req_complete приходит без пары. После req_complete память запроса освобождается, и тот же адрес req может появиться снова в новом запросе. Напишите функцию check_requests(log): строки, которые не разбираются как "pid@время:имя ..." или имя которых не из трёх событий выше (в том числе virtio_blk_submit_multireq, virtqueue_pop, шум), пропускайте. Аргументы — пары "ключ значение" через пробел. Считайте запросы по адресу req и верните словарь: "ok" — сколько запросов завершилось статусом 0 после rw_complete; "failed" — адреса req, завершившиеся ненулевым статусом, в порядке завершения; "stuck" — адреса, у которых был handle, но не было req_complete, в порядке появления; "untracked" — сколько req_complete пришло для адресов без открытого handle; "errors" — список пар [номер строки с 1, вид] для нарушений: "duplicate_handle" (handle для адреса, который ещё не завершён; состояние не меняется), "rw_complete_without_handle" (rw_complete для адреса без открытого запроса), "duplicate_rw_complete" (второй rw_complete подряд для одного запроса), "ok_without_rw_complete" (статус 0 без rw_complete; такой запрос не считается в ok и закрывается).', 'def check_requests(log):
    pass
', 'Храните словарь «адрес → состояние» (handled, rw_done). Пары разбирайте так: toks = rest.split(); dict(zip(toks[0::2], toks[1::2])). Номера строк считайте по всем строкам, включая пропущенные.', '{"func": "check_requests", "tests": [{"args": ["4242@1730000000.100000:virtio_queue_notify vdev 0x55d0c8a1b2c0 n 0 vq 0x55d0c9a00010\n4242@1730000000.100050:virtqueue_pop vq 0x55d0c9a00010 elem 0x55d0c9f3a000 in_num 2 out_num 1\n4242@1730000000.100090:virtio_blk_handle_read vdev 0x55d0c8a1b2c0 req 0x55d0c9f3a000 sector 2048 nsectors 8\n4242@1730000000.100200:virtio_blk_rw_complete vdev 0x55d0c8a1b2c0 req 0x55d0c9f3a000 ret 0\n4242@1730000000.100230:virtio_blk_req_complete vdev 0x55d0c8a1b2c0 req 0x55d0c9f3a000 status 0\n4242@1730000000.100300:virtio_notify vdev 0x55d0c8a1b2c0 vq 0x55d0c9a00010\n"], "expected": {"ok": 1, "failed": [], "stuck": [], "untracked": 0, "errors": []}}, {"args": ["4242@1730000001.000001:virtio_blk_handle_write vdev 0xA req 0x1000 sector 0 nsectors 8\n4242@1730000001.000002:virtio_blk_handle_write vdev 0xA req 0x2000 sector 8 nsectors 8\n4242@1730000001.000003:virtio_blk_submit_multireq vdev 0xA mrb 0x7ff0 start 0 num_reqs 2 offset 0 size 8192 is_write 1\n4242@1730000001.000100:virtio_blk_rw_complete vdev 0xA req 0x1000 ret 0\n4242@1730000001.000101:virtio_blk_req_complete vdev 0xA req 0x1000 status 0\n4242@1730000001.000102:virtio_blk_rw_complete vdev 0xA req 0x2000 ret 0\n4242@1730000001.000103:virtio_blk_req_complete vdev 0xA req 0x2000 status 0\n4242@1730000001.000500:virtio_blk_handle_read vdev 0xA req 0x1000 sector 16 nsectors 8\n4242@1730000001.000600:virtio_blk_rw_complete vdev 0xA req 0x1000 ret 0\n4242@1730000001.000601:virtio_blk_req_complete vdev 0xA req 0x1000 status 0\n"], "expected": {"ok": 3, "failed": [], "stuck": [], "untracked": 0, "errors": []}}, {"args": ["10@1.000001:virtio_blk_handle_read vdev 0xA req 0x10 sector 999999999 nsectors 8\n10@1.000002:virtio_blk_req_complete vdev 0xA req 0x10 status 1\n10@1.000003:virtio_blk_handle_write vdev 0xA req 0x20 sector 8 nsectors 8\n10@1.000004:virtio_blk_rw_complete vdev 0xA req 0x20 ret -5\n10@1.000005:virtio_blk_req_complete vdev 0xA req 0x20 status 1\n10@1.000006:virtio_blk_req_complete vdev 0xA req 0x30 status 0\n10@1.000007:virtio_blk_handle_read vdev 0xA req 0x40 sector 0 nsectors 1\n10@1.000008:virtio_blk_handle_read vdev 0xA req 0x50 sector 1 nsectors 1\n"], "expected": {"ok": 0, "failed": ["0x10", "0x20"], "stuck": ["0x40", "0x50"], "untracked": 1, "errors": []}}, {"args": ["this line is noise\n10@1.000001:virtio_blk_rw_complete vdev 0xA req 0x10 ret 0\n10@1.000002:virtio_blk_handle_read vdev 0xA req 0x20 sector 0 nsectors 1\n10@1.000003:virtio_blk_handle_read vdev 0xA req 0x20 sector 1 nsectors 1\n10@1.000004:virtio_blk_rw_complete vdev 0xA req 0x20 ret 0\n10@1.000005:virtio_blk_rw_complete vdev 0xA req 0x20 ret 0\n10@1.000006:virtio_blk_req_complete vdev 0xA req 0x20 status 0\n10@1.000007:virtio_blk_handle_write vdev 0xA req 0x60 sector 1 nsectors 1\n10@1.000008:virtio_blk_req_complete vdev 0xA req 0x60 status 0\n"], "expected": {"ok": 1, "failed": [], "stuck": [], "untracked": 0, "errors": [[2, "rw_complete_without_handle"], [4, "duplicate_handle"], [6, "duplicate_rw_complete"], [9, "ok_without_rw_complete"]]}}, {"args": [""], "expected": {"ok": 0, "failed": [], "stuck": [], "untracked": 0, "errors": []}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-should-notify', 8, 'func', 'Нужно ли будить гостя прерыванием', 'После virtqueue_push устройство вызывает virtio_notify; тот решает, слать ли гостю прерывание, функцией virtio_split_should_notify (hw/virtio/virtio.c, QEMU 10.2.0). Логика такая. (1) Если принят признак NOTIFY_ON_EMPTY и очередь простаивает (в работе нет запросов и avail пуст) — всегда "да", и это решение не трогает состояние. (2) Иначе без признака EVENT_IDX ответ — "да", если в avail_flags НЕ установлен бит 1 (VRING_AVAIL_F_NO_INTERRUPT); состояние не трогается. (3) Иначе (с EVENT_IDX): состояние — флаг signalled_valid (сначала ложь) и число signalled_used (сначала 0). v = signalled_valid; signalled_valid = истина; old = signalled_used; new = used_idx; signalled_used = new; ответ — "да", если not v или vring_need_event(used_event, new, old). vring_need_event(event_idx, new_idx, old) из virtio_ring.h: (uint16)(new_idx - event_idx - 1) < (uint16)(new_idx - old), все вычисления по модулю 65536. Напишите функцию notify_decisions(features, avail_flags, start_used_idx, calls): features — список строк ("EVENT_IDX", "NOTIFY_ON_EMPTY"), calls — список пар (used_event, idle), по одной на возвращённый элемент; перед каждым вызовом used_idx увеличивается на 1 по модулю 65536 (начиная со start_used_idx), used_event — то, что гость записал в кольцо к этому моменту. Верните список True/False — решение для каждого вызова.', 'def notify_decisions(features, avail_flags, start_used_idx, calls):
    pass
', 'Сначала ветка NOTIFY_ON_EMPTY, затем ветка без EVENT_IDX, и только потом работа с состоянием. Разность считайте с маской & 0xFFFF.', '{"func": "notify_decisions", "tests": [{"args": [[], 0, 0, [[0, false], [0, false]]], "expected": [true, true]}, {"args": [[], 1, 0, [[0, false], [0, false], [0, true]]], "expected": [false, false, false]}, {"args": [["NOTIFY_ON_EMPTY"], 1, 5, [[0, false], [0, true], [0, false]]], "expected": [false, true, false]}, {"args": [["EVENT_IDX"], 0, 10, [[0, false], [13, false], [13, false], [13, false]]], "expected": [true, false, false, true]}, {"args": [["EVENT_IDX"], 1, 10, [[10, false], [11, false], [12, false]]], "expected": [true, true, true]}, {"args": [["EVENT_IDX", "NOTIFY_ON_EMPTY"], 0, 100, [[200, false], [200, true], [200, false], [103, false]]], "expected": [true, true, false, true]}, {"args": [["EVENT_IDX"], 0, 65534, [[0, false], [65534, false], [1, false], [1, false]]], "expected": [true, false, false, true]}, {"args": [["EVENT_IDX"], 0, 0, []], "expected": []}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 30, 'la30-iothreads-parse', 9, 'func', 'Разбор списка iothread', 'Список iothread QEMU можно получить двумя способами. Команда монитора info iothreads (hmp_info_iothreads, QEMU 10.2.0) печатает для каждого блок: строка "<id>:", затем строки с двумя пробелами в начале "  thread_id=<n>", "  poll-max-ns=<n>", "  poll-grow=<n>", "  poll-shrink=<n>", "  aio-max-batch=<n>". QMP-команда query-iothreads отвечает JSON-объектом {"return": [{"id": ..., "thread-id": ..., "poll-max-ns": ..., ...}, ...]}; в примере из qapi/misc.json у элементов бывают только id и thread-id. Напишите функцию iothread_table(text): определите формат (текст, начинающийся с "{" или "[", — JSON; допустим и просто список элементов; иначе — вывод монитора) и верните список троек [id, thread_id, polling] в порядке появления, где polling — истина, если poll-max-ns больше нуля (если ключа нет, считайте 0). Пустой или состоящий из пробелов текст даёт пустой список. В выводе монитора пустые строки и перевод строки \r пропускайте, неизвестные ключи и строки без "=" — тоже.', 'def iothread_table(text):
    pass
', 'Для JSON хватит json.loads: результат — словарь с ключом return или сам список. Для вывода монитора строка без начального пробела и с двоеточием в конце открывает новый блок, остальные строки — пары ключ=значение.', '{"func": "iothread_table", "tests": [{"args": ["iothread0:\n  thread_id=3134\n  poll-max-ns=32768\n  poll-grow=0\n  poll-shrink=0\n  aio-max-batch=0\nmon_iothread:\n  thread_id=3135\n  poll-max-ns=0\n  poll-grow=0\n  poll-shrink=0\n  aio-max-batch=0\n"], "expected": [["iothread0", 3134, true], ["mon_iothread", 3135, false]]}, {"args": ["{\"return\": [{\"id\": \"iothread0\", \"thread-id\": 3134, \"poll-max-ns\": 32768, \"poll-grow\": 0, \"poll-shrink\": 0, \"aio-max-batch\": 0}, {\"id\": \"iothread1\", \"thread-id\": 3135, \"poll-max-ns\": 0, \"poll-grow\": 0, \"poll-shrink\": 0, \"aio-max-batch\": 0}]}"], "expected": [["iothread0", 3134, true], ["iothread1", 3135, false]]}, {"args": ["{\"return\": [{\"id\": \"iothread0\", \"thread-id\": 3134}, {\"id\": \"iothread1\", \"thread-id\": 3135}]}"], "expected": [["iothread0", 3134, false], ["iothread1", 3135, false]]}, {"args": ["  \n"], "expected": []}, {"args": ["[{\"id\": \"io\", \"thread-id\": 7, \"poll-max-ns\": 1}]"], "expected": [["io", 7, true]]}, {"args": ["io1:\r\n  thread_id=11\r\n\r\n  poll-max-ns=100\r\n  future-key=5\r\n  junk line\r\n"], "expected": [["io1", 11, true]]}, {"args": ["{\"return\": []}"], "expected": []}]}');
